'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const material=read('docs/scifi-ui/scripts/formatx-core-mesh3d-material-v18.js');
const shape=read('docs/scifi-ui/scripts/formatx-core-shape-v14.js');
const geometry=read('docs/scifi-ui/scripts/formatx-core-geometry-v13.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v11.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v11.js');
const grade=read('docs/scifi-ui/styles/formatx-core-cinematic-grade-v18.css');
const kick=read('docs/scifi-ui/scripts/formatx-core-cinematic-kick-v11.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');
assert.match(mapper,/fxApexSceneStability==='ready-v28'/);
assert.match(mapper,/formatx-core-mesh3d-material-v18\.js\?v=20260809-sparse-hdr-facets-v18/);
assert.match(mapper,/formatx-core-cinematic-grade-v18\.css\?v=20260809-high-dynamic-facets-v18/);
assert.match(mapper,/reference-glass-v18-sparse-high-dynamic-facets/);
assert.match(mapper,/reference-contrast-distribution-v18/);
assert.match(material,/vec2 cp=vec2\(vP\.x,vP\.y-\.18\)/);
assert.match(material,/float webA=/);
assert.match(material,/float webB=/);
assert.match(material,/float webC=/);
assert.match(material,/float micro=/);
assert.match(material,/float whiteFacet=/);
assert.match(material,/fxCoreHighlightModel='sparse-high-dynamic-facets-v18'/);
assert.match(material,/fxCoreMeshMaterial='reference-glass-v18'/);
assert.match(shape,/aPosition\.y\*\.72/);
assert.match(geometry,/value\*1\.15/);
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/);
assert.match(fracture,/gl\.drawElements\(gl\.LINES/);
assert.match(grade,/brightness\(1\.64\)/);
assert.match(grade,/saturate\(1\.14\)/);
assert.match(grade,/opacity: 0\.68/);
assert.match(kick,/formatx:organismresponse.*\.74,1\.15,2100/s);
assert.match(infinite,/const VERSION = 'seamless-v7'/);
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/);
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/);
console.log('PASS: v18 redistributes light into sparse high-dynamic glass facets while preserving true centered WebGL2 geometry, cinematic reaction and native scrolling.');
